import os, csv, json
from pathlib import Path
from collections import deque

date = "20190114"
NDIR = Path(os.environ["NODE_FLOW_DIR"])
PDIR = Path(os.environ["PIPELINE_FLOW_DIR"])

nodes = {}
with open(NDIR / f"{date}_node.csv", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        nodes[row["node_name"]] = row

adj = {}
edges = []
with open(PDIR / f"{date}_pipeline.csv", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        s, t, p = row["source"], row["target"], row["pipeline_name"]
        edges.append((s, t, p))
        adj.setdefault(s, []).append((t, p))
        adj.setdefault(t, []).append((s, p))  # treat as undirected for reachability

def bfs(src, dst):
    q = deque([(src, [])])
    seen = {src}
    while q:
        cur, path = q.popleft()
        if cur == dst:
            return path
        for nxt, p in adj.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, path + [{"source": cur, "target": nxt, "pipeline": p}]))
    return None

target = "南京站"
result = {}
for src in ["靖边站", "榆林站"]:
    result[src] = bfs(src, target)

print(json.dumps(result, ensure_ascii=False, indent=1))

