import os, csv, json
from pathlib import Path
from collections import deque

date = "20190114"
DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
csv_path = DIR / f"{date}_pipeline.csv"

adj = {}
with open(csv_path, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        s = row.get("source") or row.get("source_station") or ""
        t = row.get("target") or row.get("target_station") or ""
        p = row.get("pipeline") or row.get("pipeline_name") or ""
        s, t, p = s.strip(), t.strip(), p.strip()
        if not s or not t:
            continue
        adj.setdefault(s, []).append((t, p))

target = "永清站"

def bfs(start):
    if start == target:
        return []
    q = deque([(start, [])])
    seen = {start}
    while q:
        node, path = q.popleft()
        for nxt, pipe in adj.get(node, []):
            if nxt in seen:
                continue
            npath = path + [{"source": node, "target": nxt, "pipeline": pipe}]
            if nxt == target:
                return npath
            seen.add(nxt)
            q.append((nxt, npath))
    return None

out = {}
for src in ["靖边站", "榆林站", "黑河首站", "霍尔果斯首站"]:
    out[src] = bfs(src)
print(json.dumps(out, ensure_ascii=False, indent=1))

